-- AUTO-GENERATED by make_sqlite.py from vintage_curve.mysql.sql (documented MySQL->SQLite swaps only)
WITH cohort AS (
  SELECT account_id
  FROM   accounts
  WHERE  origination_month = '2025-01-01'
),
snap AS (
  SELECT s.account_id, s.dpd_bucket,
    ((CAST(strftime('%Y', s.snapshot_month) AS INTEGER) * 12 + CAST(strftime('%m', s.snapshot_month) AS INTEGER)) - (CAST(strftime('%Y', a.origination_month) AS INTEGER) * 12 + CAST(strftime('%m', a.origination_month) AS INTEGER))) AS months_on_book
  FROM monthly_snapshots s
  JOIN accounts a ON a.account_id = s.account_id
  JOIN cohort   c ON c.account_id = s.account_id
),
scoped AS (
  SELECT * FROM snap WHERE months_on_book IN (3, 6, 9)
),
bucketed AS (
  SELECT months_on_book, dpd_bucket,
    COUNT(*) AS accounts_in_bucket,
    SUM(COUNT(*)) OVER (
      PARTITION BY months_on_book
    ) AS cohort_total
  FROM scoped
  GROUP BY months_on_book, dpd_bucket
)
SELECT months_on_book, dpd_bucket, accounts_in_bucket,
  ROUND(100.0 * accounts_in_bucket / cohort_total, 1)
    AS pct_of_cohort
FROM bucketed
ORDER BY months_on_book,
  CASE dpd_bucket WHEN 'current' THEN 1 WHEN '30' THEN 2 WHEN '60' THEN 3 WHEN '90+' THEN 4 WHEN 'charge_off' THEN 5 END;
